  partialApproveRequest(auth: AccessClaims, id: string, input: any, key: string, requestId: string) {
    return this.command(auth, "procurement.request.partially_approve", key, { id, ...input }, async (c) => {
      const row = (await c.query<any>("SELECT * FROM procurement_purchase_requests WHERE tenant_id=$1 AND id=$2 FOR UPDATE", [auth.tenantId, id])).rows[0];
      if (!row) this.notFound("PURCHASE_REQUEST_NOT_FOUND");
      if (input.version != null && Number(input.version) !== row.version) this.conflict("VERSION_CONFLICT");
      if (row.requester_user_id === auth.userId) this.conflict("DUAL_CONTROL_REQUIRED");
      if (row.status !== "SUBMITTED" && row.status !== "PARTIALLY_APPROVED") this.conflict("PURCHASE_REQUEST_STATUS_INVALID");
      const requested = (await c.query<any>("SELECT * FROM procurement_purchase_request_lines WHERE tenant_id=$1 AND purchase_request_id=$2 FOR UPDATE", [auth.tenantId, id])).rows;
      const allocations = Array.isArray(input.lines) ? input.lines : [];
      if (!allocations.length) this.conflict("PURCHASE_REQUEST_LINE_APPROVAL_REQUIRED");
      const byId = new Map(requested.map((line: any) => [line.id, line]));
      let total = 0n;
      for (const allocation of allocations) {
        const line = byId.get(allocation.requestLineId);
        if (!line) this.conflict("PURCHASE_REQUEST_LINE_NOT_FOUND");
        const quantity = q(String(allocation.approvedQuantity ?? "0"));
        const requestedQuantity = q(String(line.quantity));
        const amount = BigInt(allocation.approvedAmountMinor ?? "0");
        if (quantity < 0n || quantity > requestedQuantity || amount < 0n || amount > BigInt(line.amount_minor)) this.conflict("PURCHASE_REQUEST_APPROVAL_CAP_EXCEEDED");
        total += amount;
        await c.query("UPDATE procurement_purchase_request_lines SET approved_quantity=$4::numeric,approved_amount_minor=$5 WHERE tenant_id=$1 AND purchase_request_id=$2 AND id=$3", [auth.tenantId, id, line.id, (Number(quantity) / 1_000_000).toFixed(6), amount.toString()]);
      }
      if (input.approvedTotalMinor != null && total !== BigInt(input.approvedTotalMinor)) this.conflict("PURCHASE_REQUEST_APPROVAL_TOTAL_MISMATCH");
      const fingerprint = hash({ requestId: id, version: row.version, lines: allocations, total: total.toString() });
      const updated = (await c.query<any>("UPDATE procurement_purchase_requests SET status='PARTIALLY_APPROVED',approved_total_minor=$3,version=version+1,updated_at=now() WHERE tenant_id=$1 AND id=$2 RETURNING *", [auth.tenantId, id, total.toString()])).rows[0];
      await c.query("INSERT INTO procurement_purchase_request_approvals(tenant_id,purchase_request_id,approver_user_id,decision,approved_amount_minor,version,evidence_json,request_id,allocation_json,allocation_fingerprint) VALUES($1,$2,$3,'PARTIALLY_APPROVED',$4,$5,$6,$7,$8,$9)", [auth.tenantId, id, auth.userId, total.toString(), row.version, JSON.stringify({ reason: input.reason }), requestId, JSON.stringify(allocations), fingerprint]);
      await this.history(c, "procurement_purchase_request_history", "purchase_request_id", id, auth, row.status, "PARTIALLY_APPROVED", requestId, input.reason);
      await this.evidence(c, auth, "procurement.request.partially_approved", "procurement_purchase_request", id, requestId, row.branch_id, { fingerprint, total: total.toString() });
      return updated;
    });
  }
